-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.approve_page_submission(p_submission_id uuid, p_readiness_policy_version integer, p_override_reason text, p_readiness jsonb)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.approve_page_submission(p_submission_id uuid, p_readiness_policy_version integer, p_override_reason text, p_readiness jsonb)
 RETURNS TABLE(published_version_id uuid, revision bigint, path text, shell_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
DECLARE
  actor uuid; visible RECORD; head RECORD; request RECORD; src RECORD; published RECORD; story_pin public.story_review_pins%ROWTYPE; story_head public.collections%ROWTYPE; current_story RECORD;
BEGIN
  actor := app.require_actor();

  -- First scope the identifier to this session. A guessed id from another site
  -- gets the same answer as an id that does not exist.
  SELECT s.item_id, s.site_id INTO visible
    FROM public.submissions s
   WHERE s.id = p_submission_id AND app.has_page_access(s.item_id);
  IF visible IS NULL THEN RAISE EXCEPTION 'no such submission' USING ERRCODE = 'CMS03'; END IF;

  -- Page before submission is the global lock order. Saving holds the page and
  -- may supersede a submission from its trigger; using the opposite order here
  -- would turn an ordinary save/review race into a deadlock.
  SELECT p.id, p.site_id, p.revision, p.draft_version_id, p.archived_at
    INTO head FROM public.pages p WHERE p.id = visible.item_id FOR UPDATE;
  IF head IS NULL OR head.site_id <> visible.site_id THEN
    RAISE EXCEPTION 'submission does not name a page in its site' USING ERRCODE = 'CMS04';
  END IF;
  IF NOT app.can_publish_page(head.id) THEN
    RAISE EXCEPTION 'not permitted to review this site' USING ERRCODE = 'CMS02';
  END IF;

  SELECT * INTO story_pin FROM public.story_review_pins WHERE submission_id=p_submission_id;
  IF story_pin.submission_id IS NOT NULL THEN
   SELECT * INTO story_head FROM public.collections WHERE id=story_pin.collection_id AND site_id=head.site_id AND reader_key='stories' FOR UPDATE;
   SELECT e.archived_at,v.schema_version_id,v.values INTO current_story FROM public.collection_entries e
   JOIN public.collection_entry_versions v ON v.id=e.draft_version_id WHERE e.id=story_pin.entry_id AND e.collection_id=story_head.id FOR UPDATE OF e;
  END IF;

  SELECT s.id, s.site_id, s.item_type, s.item_id, s.version_id, s.status
    INTO request FROM public.submissions s WHERE s.id = p_submission_id FOR UPDATE;
  IF request.item_type <> 'page' OR request.item_id <> head.id OR request.site_id <> head.site_id THEN
    RAISE EXCEPTION 'submission does not match this page' USING ERRCODE = 'CMS04';
  END IF;
  IF request.status <> 'open' THEN
    RAISE EXCEPTION 'submission is no longer waiting for review' USING ERRCODE = 'CMS04';
  END IF;
  IF head.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'page is archived' USING ERRCODE = 'CMS04';
  END IF;
  IF head.draft_version_id IS DISTINCT FROM request.version_id THEN
    RAISE EXCEPTION 'the page changed after it was submitted'
      USING ERRCODE = 'CMS01', DETAIL = head.revision::text;
  END IF;

  SELECT pv.id, pv.carries_trusted_code, pv.trusted_code_approved_by
    INTO src FROM public.page_versions pv
   WHERE pv.id = request.version_id AND pv.page_id = head.id AND pv.site_id = head.site_id;
  IF src IS NULL THEN
    RAISE EXCEPTION 'submitted version does not belong to this page' USING ERRCODE = 'CMS04';
  END IF;

  -- The queue is where a super admin can approve the exact raw-code version
  -- they are reviewing. An editor cannot turn an approval decision into a way
  -- around that boundary.
  IF src.carries_trusted_code AND src.trusted_code_approved_by IS NULL THEN
    IF NOT app.is_super_admin() THEN
      RAISE EXCEPTION 'version carries raw markup and needs super-admin approval'
        USING ERRCODE = 'CMS05';
    END IF;
    UPDATE public.page_versions
       SET trusted_code_approved_by = actor, trusted_code_approved_at = now()
     WHERE id = src.id;
    PERFORM app.write_audit(
      head.site_id, 'user', actor, 'page.approve_trusted_code', 'page', head.id,
      NULL, src.id, jsonb_build_object('submission_id', request.id)
    );
  END IF;

  IF story_pin.submission_id IS NOT NULL THEN
   IF story_pin.page_version_id<>request.version_id OR current_story IS NULL OR current_story.archived_at IS NOT NULL
    OR story_head.draft_schema_version_id IS DISTINCT FROM story_pin.schema_version_id
    OR current_story.schema_version_id IS DISTINCT FROM story_pin.schema_version_id
    OR current_story.values IS DISTINCT FROM (SELECT v.values FROM public.collection_entry_versions v WHERE v.id=story_pin.entry_version_id) THEN
    RAISE EXCEPTION 'The story changed after review. Ask its author to submit again.' USING ERRCODE='CMS01';END IF;
   IF story_head.published_schema_version_id IS DISTINCT FROM story_pin.schema_version_id THEN
    RAISE EXCEPTION 'Publish the saved Stories settings first, then review this story again.' USING ERRCODE='CMS04';END IF;
   IF COALESCE(current_story.values->>'published_date','')='' THEN
    RAISE EXCEPTION 'Choose a story date, save and submit again before publication.' USING ERRCODE='CMS04';END IF;
   PERFORM * FROM app.publish_story_entries(story_head.id,story_head.entry_revision,ARRAY[story_pin.entry_id]);
  ELSIF EXISTS(SELECT 1 FROM public.collections c JOIN public.collection_entries e ON e.collection_id=c.id
   JOIN public.collection_entry_versions v ON v.id=e.draft_version_id JOIN public.pages p ON p.id=head.id
   WHERE c.site_id=head.site_id AND c.reader_key='stories' AND e.archived_at IS NULL AND v.values->>'story_url'=app.page_path(p.slug)) THEN
   RAISE EXCEPTION 'Submit this story again so its saved text can be reviewed with its article.' USING ERRCODE='CMS04';
  END IF;

  SELECT * INTO published FROM app.publish_page_version(
    head.id, head.revision, request.version_id, 'user', actor,
    p_readiness_policy_version, NULLIF(btrim(COALESCE(p_override_reason, '')), ''),
    p_readiness, jsonb_build_object('submission_id', request.id)
  );

  UPDATE public.submissions
     SET status = 'approved', decided_by = actor, decided_at = now(), decision_note = ''
   WHERE id = request.id;

  PERFORM app.write_audit(
    head.site_id, 'user', actor, 'submission.approved', 'submission', request.id,
    request.version_id, published.published_version_id,
    jsonb_build_object('page_id', head.id, 'revision', published.revision)
  );

  RETURN QUERY SELECT published.published_version_id, published.revision,
                      published.path, published.shell_revision;
END
$function$
